```c
#include <stddef.h>

typedef struct {
    float ie;
    float alpha;
    float beta;
    float gamma;
} bjt_gains_t;

int bjt_gains(float ic, float ib, bjt_gains_t *out)
{
    if (out == NULL || ib <= 0.0f || ic < 0.0f) {
        return 0;
    }
    out->ie = ic + ib;
    out->alpha = ic / out->ie;
    out->beta = ic / ib;
    out->gamma = out->ie / ib;
    return 1;
}
