    int bc_fwd = vb > vc;

    if (be_fwd && !bc_fwd) {
        return REGION_ACTIVE;
    }
    if (be_fwd && bc_fwd) {
        return REGION_SATURATION;
    }
    if (!be_fwd && bc_fwd) {
