```c
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define VCC_MV 12000
#define VBE_SILICON_MV 700
#define RB_OHM 470000
#define RC_OHM 2200
#define BETA_DC 100
#define UA_PER_MA 1000

int main(void)
{
    int32_t ib_ua;
    int32_t ic_ua;
    int32_t vce_mv;

    ib_ua = ((VCC_MV - VBE_SILICON_MV) * UA_PER_MA) / RB_OHM;
    ic_ua = BETA_DC * ib_ua;
    vce_mv = VCC_MV - ((ic_ua * RC_OHM) / UA_PER_MA);

    printf("IB=%d uA IC=%d uA VCE=%d mV\n", ib_ua, ic_ua, vce_mv);
    return EXIT_SUCCESS;
}
```
This program applies the fixed-bias relation I_B = (V_CC - V_BE)/R_B. It then uses I_C = beta I_B and V_CE = V_CC - I_C R_C. Every product is scaled by the uA-per-mA factor so the units stay consistent.

```c
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define VCC_MV 12000
#define VBE_SILICON_MV 700
#define RB_OHM 470000
#define RC_OHM 2200
#define BETA_DC 100
#define CURRENT_GAIN_OFFSET 1
#define UA_PER_MA 1000

int main(void)
{
    int32_t denom_ohm;
    int32_t ib_ua;
    int32_t ic_ua;
    int32_t vc_mv;

    denom_ohm = RB_OHM + ((BETA_DC + CURRENT_GAIN_OFFSET) * RC_OHM);
    ib_ua = ((VCC_MV - VBE_SILICON_MV) * UA_PER_MA) / denom_ohm;
    ic_ua = BETA_DC * ib_ua;
    vc_mv = VCC_MV - (((ic_ua + ib_ua) * RC_OHM) / UA_PER_MA);

    printf("IB=%d uA IC=%d uA VC=%d mV\n", ib_ua, ic_ua, vc_mv);
    return EXIT_SUCCESS;
}
```
The base current uses the collector-to-base feedback denominator. The collector current is beta times I_B. The collector voltage subtracts the drop from both I_C and I_B across R_C.

```c
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>

#define VCC_MV 12000
#define R1_OHM 47000
#define R2_OHM 10000
#define RE_OHM 1000
#define RC_OHM 2200
#define BETA_DC 100
#define VBE_SILICON_MV 700
#define CURRENT_GAIN_OFFSET 1
#define UA_PER_MA 1000

int main(void)
{
    int32_t vth_mv;
    int32_t rth_ohm;
    int32_t ib_ua;
    int32_t ic_ua;
    int32_t ie_ua;
    int32_t ve_mv;
    int32_t vc_mv;
    int32_t vce_mv;

    vth_mv = (VCC_MV * R2_OHM) / (R1_OHM + R2_OHM);
    rth_ohm = (R1_OHM * R2_OHM) / (R1_OHM + R2_OHM);
    ib_ua = ((vth_mv - VBE_SILICON_MV) * UA_PER_MA) / (rth_ohm + ((BETA_DC + CURRENT_GAIN_OFFSET) * RE_OHM));
    ic_ua = BETA_DC * ib_ua;
    ie_ua = ic_ua + ib_ua;
    ve_mv = (ie_ua * RE_OHM) / UA_PER_MA;
    vc_mv = VCC_MV - ((ic_ua * RC_OHM) / UA_PER_MA);
