    float c_ox;
    float e_ox;
    float q;
} oxide_result_t;

oxide_result_t oxide_calc(float eps_ox, float area_m2, float t_ox_m, float v_ox_v)
{
    oxide_result_t r = {0.0f, 0.0f, 0.0f};
    if (t_ox_m <= 0.0f) {
        return r;
    }
    r.c_ox = (eps_ox * area_m2) / t_ox_m;
    r.e_ox = v_ox_v / t_ox_m;
    r.q = r.c_ox * v_ox_v;
    return r;
}
```
All three results come from the simplified capacitor model: Cox = eps_ox * A / t_ox, E_ox = V_ox / t_ox and Q = C * V.

